function useContentCreationPreference() {
  const queryClient = useQueryClient();
  const { data: session } = useSuspenseQuery(
    orpc.session.getSession.queryOptions({})
  );
  const preference = session?.user?.contentCreationMode || "plan";
  const updateMutation = useMutation({
    mutationFn: async (mode) => {
      return authClient.updateUser({
        contentCreationMode: mode
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: orpc.session.getSession.queryKey({})
      });
    }
  });
  const updatePreference = (mode) => {
    updateMutation.mutate(mode);
  };
  return {
    preference,
    updatePreference,
    isPending: updateMutation.isPending
  };
}
